SELECT CAST(reporting_month AS VARCHAR) AS reporting_month, campaign_id, campaign_name, attributed_net_revenue_gbp, ROW_NUMBER() OVER (PARTITION BY reporting_month ORDER BY attributed_net_revenue_gbp DESC, campaign_id ASC) AS monthly_rank FROM MarketingCampaignMonthly QUALIFY ROW_NUMBER() OVER (PARTITION BY reporting_month ORDER BY attributed_net_revenue_gbp DESC, campaign_id ASC) <= 3 ORDER BY reporting_month ASC, monthly_rank ASC
